// Quiz component — a 5-question comprehension check generated by LiveReview
// alongside the summary (see reviewData.quiz). Static per review: answers
// aren't re-fetched or regenerated on retry, just cleared.
import { waitForPreact } from './utils.js';

const OPTION_LETTERS = ['A', 'B', 'C', 'D'];

function escapeHTML(text) {
    return text
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

function renderQuizContent(text) {
    if (!text) return '';
    let result = escapeHTML(text);
    result = result.replace(/```([\s\S]*?)```/g, (_, code) => {
        return '<pre class="quiz-code-block"><code>' + code.trim() + '</code></pre>';
    });
    result = result.replace(/`([^`]+)`/g, '<code class="quiz-code-inline">$1</code>');
    return result;
}

export async function createQuiz() {
    const { html, useState } = await waitForPreact();

    return function Quiz({ quiz }) {
        const [selected, setSelected] = useState({});
        const [submitted, setSubmitted] = useState(false);

        if (!quiz || quiz.length === 0) {
            return html`
                <div class="quiz-empty">No quiz was generated for this review.</div>
            `;
        }

        const answeredCount = Object.keys(selected).length;
        const allAnswered = answeredCount === quiz.length;
        const score = submitted
            ? quiz.reduce((sum, q, idx) => sum + (selected[idx] === q.correctIndex ? 1 : 0), 0)
            : 0;

        const choose = (questionIdx, optionIdx) => {
            if (submitted) return;
            setSelected(prev => ({ ...prev, [questionIdx]: optionIdx }));
        };

        const handleSubmit = () => setSubmitted(true);
        const handleRetry = () => {
            setSelected({});
            setSubmitted(false);
        };

        return html`
            <div class="quiz-container">
                ${submitted && html`
                    <div class="quiz-score-banner">
                        <span>You scored <b>${score}/${quiz.length}</b></span>
                        <button class="action-btn" onClick=${handleRetry}>Try Again</button>
                    </div>
                `}
                ${quiz.map((q, qIdx) => html`
                    <div class="quiz-question" key=${qIdx}>
                        <div class="quiz-question-text">
                            ${qIdx + 1 + '. '}<span dangerouslySetInnerHTML=${{ __html: renderQuizContent(q.question) }}></span>
                        </div>
                        <div class="quiz-options">
                            ${(q.options || []).map((opt, oIdx) => {
                                const isChosen = selected[qIdx] === oIdx;
                                const isCorrect = oIdx === q.correctIndex;
                                let cls = 'quiz-option';
                                if (isChosen && !submitted) cls += ' chosen';
                                if (submitted && isCorrect) cls += ' correct';
                                if (submitted && isChosen && !isCorrect) cls += ' incorrect';
                                return html`
                                    <button
                                        class=${cls}
                                        onClick=${() => choose(qIdx, oIdx)}
                                        disabled=${submitted}
                                    >
                                        <span class="quiz-option-letter">${OPTION_LETTERS[oIdx] || oIdx + 1}</span>
                                        <span class="quiz-option-text" dangerouslySetInnerHTML=${{ __html: renderQuizContent(opt) }}></span>
                                    </button>
                                `;
                            })}
                        </div>
                        ${submitted && q.explanation && html`
                            <div class="quiz-explanation" dangerouslySetInnerHTML=${{ __html: renderQuizContent(q.explanation) }}></div>
                        `}
                    </div>
                `)}
                ${!submitted && html`
                    <button class="btn btn-primary quiz-submit-btn" onClick=${handleSubmit} disabled=${!allAnswered}>
                        Check My Answers (${answeredCount}/${quiz.length} answered)
                    </button>
                `}
            </div>
        `;
    };
}

let QuizComponent = null;
export async function getQuiz() {
    if (!QuizComponent) {
        QuizComponent = await createQuiz();
    }
    return QuizComponent;
}
